<script setup>
import {ref,computed,watch,nextTick,onMounted,onUnmounted} from 'vue';import {Head,Link,usePage,router} from '@inertiajs/vue3';import axios from 'axios';
import Feedback from '../Components/Feedback.vue';import {art,crew,message} from '../art';
import RecallBalance from '../Components/RecallBalance.vue';import SaveNotice from '../Components/SaveNotice.vue';import {useStudyDelivery} from '../useStudyDelivery';import {answerKey} from '../studyDelivery';
const props=defineProps({deck:Object}),page=usePage(),data=ref(props.deck),sessionBusy=ref(false),sessionError=ref(''),saved=ref(''),goalDialog=ref(null);
const q=computed(()=>data.value.question),labels=['Unfamiliar','Unsure','Somewhat familiar','Mostly confident','Confident'];
async function goal(){await nextTick();if(data.value.goal_prompt&&!data.value.finished&&!goalDialog.value?.open)goalDialog.value?.showModal();else if(!data.value.goal_prompt)goalDialog.value?.close()}
watch(()=>data.value.goal_prompt,goal);onMounted(goal);
function accept(r){data.value=r.data.deck;if(r.data.achievement)page.props.achievement=r.data.achievement;if(r.data.community)page.props.community=r.data.community}
const delivery=useStudyDelivery('sushi:pending:'+page.props.user.id+':deck:'+data.value.id,'/flashcards/decks/'+data.value.id,accept);
const {pending,status,retry,discard}=delivery,busy=computed(()=>sessionBusy.value||delivery.busy.value||!!pending.value),error=computed(()=>sessionError.value||delivery.error.value);
async function answer(value){if(busy.value)return;saved.value='';sessionError.value='';await delivery.send('answer',{question_id:q.value.id,answer:value,token:q.value.token})}
async function rate(confidence){if(busy.value)return;sessionError.value='';await delivery.send('rate',{question_id:q.value.id,confidence,token:q.value.token});if(!pending.value){saved.value='Familiarity saved.';window.scrollTo({top:0,behavior:'instant'})}}
function exitCheck(){if(busy.value)return;router.post('/flashcards/decks/'+data.value.id+'/exit-check',{session_number:data.value.session_number})}
function reload(){discard();router.reload()}
async function session(action){if(busy.value)return;sessionBusy.value=true;sessionError.value='';try{accept(await axios.post('/flashcards/decks/'+data.value.id+'/session',{action,session_number:data.value.session_number}));goalDialog.value?.close();if(action==='resume')await goal()}catch(e){sessionError.value=message(e)}finally{sessionBusy.value=false}}
function keys(e){const key=answerKey(e);if(!key||busy.value||!q.value||data.value.finished||goalDialog.value?.open)return;if(q.value.answer!==null){if(!/^[1-5]$/.test(e.key))return;e.preventDefault();rate(key)}else if(key<=4){e.preventDefault();answer(String.fromCharCode(64+key))}}
onMounted(()=>window.addEventListener('keydown',keys));onUnmounted(()=>window.removeEventListener('keydown',keys));
let pulse;onMounted(()=>{pulse=setInterval(()=>{if(!document.hidden&&!data.value.finished)axios.post('/study/active').catch(()=>{})},60000)});onUnmounted(()=>clearInterval(pulse));
</script>
<template><Head :title="data.title"/><div class="page-title"><div><p class="eyebrow">Memory Maki · {{data.total}} questions · {{data.reviews}} ratings</p><h1>{{data.title}}</h1><Link href="/flashcards">Choose or build another deck</Link></div><img class="portrait" :src="art.memo" alt="Memo Maki"></div>
<section class="deck-stats" aria-label="Familiarity distribution for this deck" aria-live="polite"><div v-for="(count,i) in data.counts" :key="i" :class="'rating-'+i" :aria-label="(i===0?'Unrated':i+' '+labels[i-1])+': '+count"><strong>{{count}}</strong><span>{{i===0?'Unrated':'Rating '+i}}</span></div></section>
<RecallBalance :calibration="data.calibration" :accuracy="data.accuracy"/><div class="panel" v-if="data.exit_quiz||data.counts[5]>=data.goal_target"><h2>One last tasting</h2><p>Try a short recall check with answers revealed at the end.</p><Link v-if="data.exit_quiz" class="button" :href="'/memory-checks/'+data.exit_quiz.id">{{data.exit_quiz.finished_at?'See recall results':'Resume recall check'}}</Link><button v-else :disabled="busy" @click="exitCheck">Take {{Math.min(5,data.total)}}-question recall check</button></div>
<div class="row"><p><strong>{{data.counts[5]}} / {{data.total}}</strong> rated 5 · {{data.goal_target}} needed for the 80% stopping point.</p><button v-if="!data.finished" :disabled="busy" @click="session('finish')">Finish session</button></div>
<SaveNotice :status="status" :error="error" :pending="pending" :busy="delivery.busy.value" @retry="retry" @reload="reload"/><p class="muted keyboard-hint">Keyboard: A–D or 1–4 answers; 1–5 rates familiarity after feedback. Keep focus outside a control.</p>
<section v-if="data.finished" class="panel session-summary"><img class="portrait large" :src="art.memo" alt="Memo celebrates your study session"><p class="eyebrow">Your roll is saved</p><h2>Session complete</h2><p>{{data.session_reviews}} ratings this session. {{data.counts[5]}} of {{data.total}} questions are currently rated confident.</p><p>{{data.counts[0]}} unrated · {{data.counts[1]+data.counts[2]}} needing more practice</p><button class="primary" :disabled="busy" @click="session('resume')">Resume this deck</button> <Link class="button" href="/">Back to the counter</Link></section>
<article v-else-if="q" class="panel flashcard"><div class="subject-line"><img class="small-portrait" :src="crew[q.subject]?.image" :alt="crew[q.subject]?.name"><div><strong>{{q.subject}}</strong><small>{{q.topic}} · {{q.id}}</small></div></div><h2 class="question-stem pre">{{q.stem}}</h2><div class="options"><button v-for="(option,i) in q.options" :key="i" :disabled="busy||q.answer!==null" :class="{selected:q.answer===String.fromCharCode(65+i),correct:q.key===String.fromCharCode(65+i)}" @click="answer(String.fromCharCode(65+i))"><strong>{{String.fromCharCode(65+i)}}.</strong> {{option}}</button></div><p v-if="q.answer" class="notice">{{q.correct?'Correct.':'Review the explanation below.'}}</p><Feedback :question="q"/><section v-if="q.answer"><h3>How well do you know this question?</h3><p>Lower ratings bring questions back more often while you study this deck.</p><div class="confidence"><button v-for="(label,i) in labels" :key="label" :class="'rating-'+(i+1)" :disabled="busy" @click="rate(i+1)"><strong>{{i+1}}</strong><span>{{label}}</span></button></div></section></article>
<p class="muted">Confidence is your own familiarity rating. It is separate from answer accuracy. Low-rated and unrated questions appear more often. Up to three other cards come between repeats, depending on deck size. There are no day-based waiting periods.</p>
<dialog ref="goalDialog" class="tier-dialog goal-dialog" @cancel.prevent="session('continue')"><img class="portrait large" :src="art.memo" alt="Memo Maki"><p class="eyebrow">80% confident</p><h2>This roll is ready!</h2><p>Session accuracy: {{data.accuracy.correct}} / {{data.accuracy.total}} rated answers correct. Confidence and accuracy measure different things.</p><p>You feel confident about {{data.counts[5]}} of {{data.total}} questions. Would you like to finish this session?</p><div class="row"><button class="primary" :disabled="busy" @click="exitCheck">Try recall check</button><button :disabled="busy" @click="session('finish')">Finish session</button><button :disabled="busy" @click="session('continue')">Keep rolling</button></div><p class="muted">Your deck and ratings stay saved either way.</p></dialog>
</template>
